      END_STATE();
    case 5:
      if (lookahead == ',') ADVANCE(31);
      if (lookahead == '/') ADVANCE(10);
      if (lookahead == '}') ADVANCE(28);
      if (('\t' <= lookahead && lookahead <= '\r') ||
          lookahead == ' ') SKIP(5);
